import { IHikingDutyDTO } from '../@types/hiking.backendTypes';
import { IHikingDuty } from '../@types/hiking.baseTypes';

export const mapHikingDutyItem = (backData: IHikingDutyDTO): IHikingDuty => {
  return {
    id: +backData.id,
    id_user: +backData.id_user,
    date: new Date(backData.date),
    comment: backData.comment,
    user: {
      id: +backData.id_user,
      name: backData.user_name,
      photo: backData.user_photo,
    },
    created: {
      id: +backData.creator_id,
      name: backData.creator_name,
      date: new Date(backData.created_at),
    },
    updated:
      backData.updated_id && backData.updated_at && backData.updated_name
        ? {
            id: +backData.updated_id,
            name: backData.updated_name,
            date: new Date(backData.updated_at),
          }
        : null,
  };
};
