import { get, handleApiError, post } from '@helpers/httpClient';

import { mapHikingDutyItem } from '../@mappers/hikingDuty.mapper';
import {
  IHikingDutyCreateDTO,
  IHikingDutyDTO,
  IHikingDutyUpdateDTO,
} from '../@types/hiking.backendTypes';
import { IHikingDuty } from '../@types/hiking.baseTypes';

export const getHikingDuty = async (id_hiking: number): Promise<IHikingDuty[]> => {
  const res = await get<IHikingDutyDTO[]>('/ajax/hiking/duty/duty.php', { id_hiking });
  return res.map(mapHikingDutyItem);
};

export const addHikingDuty = async (data: IHikingDutyCreateDTO): Promise<number> => {
  const res = await post<any, IHikingDutyCreateDTO>('/ajax/hiking/duty/duty_add.php', data).then<{
    id: string;
  }>(handleApiError);
  return +res.id;
};

export const editHikingDuty = async (data: IHikingDutyUpdateDTO): Promise<boolean> => {
  const res = await post<any, IHikingDutyUpdateDTO>('/ajax/hiking/duty/duty_edit.php', data).then<{
    success: string;
  }>(handleApiError);
  return Boolean(res?.success);
};

export const deleteHikingDuty = async (id_hiking: number, id: number): Promise<boolean> => {
  const res = await post<any, { id: number; id_hiking: number }>('/ajax/hiking/duty/duty_del.php', {
    id_hiking,
    id,
  }).then<{ success: string }>(handleApiError);
  return Boolean(res?.success);
};
